starterCodeJson.code:
// Question 1 — the cover page of the SRS template (Wiegers): fill every field, remove every <placeholder>.
const COVER = {
  title: 'Software Requirements Specification',
  project: '<Project name>',
  version: '<1.0>',
  preparedBy: '<Your full name - Student ID>',
  organization: '<Organization>',
  dateCreated: '<yyyy-mm-dd>',
};

// Question 2 — context diagram as a Mermaid flowchart (paste into https://mermaid.live to see it).
// The system = ONE circle. External entities = rectangles. One labelled arrow per direction; label = the DATA.
const CONTEXT_DIAGRAM = `
flowchart LR
  S((System name))
  E1[External entity] -->|data in| S
  S -->|data out| E1
`;

// Question 3 — use case diagram (PlantUML: paste into https://www.plantuml.com/plantuml) + the two tables of the template.
const USE_CASE_DIAGRAM = `
@startuml
left to right direction
actor "Actor name" as A1
rectangle "System name" {
  usecase "Verb Object" as UC1
}
A1 --> UC1
@enduml
`;

// Table "# | Actor | Description" — one object per actor of the diagram (same names).
const ACTORS = [
  { name: 'Actor name', description: '' },
];

// Table "# | Use Case | Actors | Description" — one object per use case (same names as the diagram).
const USE_CASES = [
  { id: 'UC-01', name: 'Verb Object', actors: ['Actor name'], description: '' },
];

// Question 4 — conceptual ERD (Mermaid erDiagram) + the entity table of the template.
const ERD = `
erDiagram
  ENTITY_A ||--o{ ENTITY_B : verb
  ENTITY_A {
    string entityAId PK
    string name
  }
`;

// Table "# | Entity | Description" (+ key attributes) — one object per entity of the ERD.
const ENTITIES = [
  { name: 'ENTITY_A', description: '', attributes: ['entityAId'] },
];

solutionCodeJson.code:
// Question 1 — copy the system name EXACTLY from the paper; the grader cannot know your name, any real one passes.
const COVER = {
  title: 'Software Requirements Specification',
  project: 'LabEquip Lab Equipment Lending System',
  version: '1.0',
  preparedBy: 'Nguyen Van An - SE180123',
  organization: 'FPT University, Ho Chi Minh City campus',
  dateCreated: '2026-11-05',
};

// Question 3 — use case diagram consistent with Question 2 (same actors), plus the actor and use case tables.
const USE_CASE_DIAGRAM = `@startuml
left to right direction
actor Student
actor "Project Supervisor" as SV
actor "Lab Technician" as LT
actor "Lab Manager" as LM
actor "Campus SSO" as SSO
actor "E-wallet" as EW
actor "Notification Service" as NS
rectangle "LabEquip Lab Equipment Lending System" {
  usecase "Sign In" as UC1
  usecase "Browse Equipment Catalogue" as UC2
  usecase "Submit Loan Request" as UC3
  usecase "Check Unpaid Fines" as UC4
  usecase "Approve Loan Request" as UC5
  usecase "Hand Over Equipment" as UC6
  usecase "Scan Unit QR Code" as UC7
  usecase "Record Equipment Return" as UC8
  usecase "Issue Fine" as UC9
  usecase "Pay Fine" as UC10
  usecase "Log Unit Maintenance" as UC11
  usecase "Retire Unit" as UC12
  usecase "Manage Equipment Catalogue" as UC13
  usecase "Manage Technician Accounts" as UC14
  usecase "View Lending Reports" as UC15
  usecase "Send Due-Date Reminder" as UC16
}
Student --> UC1
SV --> UC1
LT --> UC1
LM --> UC1
UC1 --> SSO
Student --> UC2
Student --> UC3
UC3 ..> UC4 : <<include>>
SV --> UC5
LT --> UC6
UC6 ..> UC7 : <<include>>
LT --> UC8
UC9 ..> UC8 : <<extend>>
Student --> UC10
UC10 --> EW
LT --> UC11
LT --> UC12
LM --> UC13
LM --> UC14
LM --> UC15
UC16 --> NS
@enduml
`;

const ACTORS = [
  {
    name: 'Student',
    description: 'A student who browses the catalogue, requests equipment for a project, collects and returns units and pays fines.',
  },
  {
    name: 'Project Supervisor',
    description: 'The lecturer supervising the project, who approves or rejects requests that contain a high-value model.',
  },
  {
    name: 'Lab Technician',
    description: 'Lab staff who hand over and receive units, scan their QR codes, inspect returns and log maintenance.',
  },
  {
    name: 'Lab Manager',
    description: 'Manages categories, models and values, technician accounts, and reads the lending reports.',
  },
  {
    name: 'Campus SSO',
    description: 'External university sign-on service that authenticates users and returns their identity.',
  },
  {
    name: 'E-wallet',
    description: 'External university payment service that executes fine payments and returns the result.',
  },
  {
    name: 'Notification Service',
    description: 'External university service that delivers the reminders and notices sent by LabEquip.',
  },
];

const USE_CASES = [
  {
    id: 'UC-01',
    name: 'Sign In',
    actors: ['Student', 'Project Supervisor', 'Lab Technician', 'Lab Manager', 'Campus SSO'],
    description: 'Any user signs in with the university account; Campus SSO authenticates the user and returns the identity.',
  },
  {
    id: 'UC-02',
    name: 'Browse Equipment Catalogue',
    actors: ['Student'],
    description: 'The student searches the models by category and sees description, value and available units.',
  },
  {
    id: 'UC-03',
    name: 'Submit Loan Request',
    actors: ['Student'],
    description: 'The student requests one or more models for up to 14 days and names the project they are for.',
  },
  {
    id: 'UC-04',
    name: 'Check Unpaid Fines',
    actors: [],
    description: 'Included in every request: a student with an unpaid fine is blocked from submitting a new request.',
  },
  {
    id: 'UC-05',
    name: 'Approve Loan Request',
    actors: ['Project Supervisor'],
    description: 'The supervisor approves or rejects a request that contains a model worth more than 5,000,000 VND.',
  },
  {
    id: 'UC-06',
    name: 'Hand Over Equipment',
    actors: ['Lab Technician'],
    description: 'The technician gives the student specific units for an approved request and records the loan.',
  },
  {
    id: 'UC-07',
    name: 'Scan Unit QR Code',
    actors: [],
    description: 'Included in every handover: scanning a unit links that serial-numbered unit to the loan.',
  },
  {
    id: 'UC-08',
    name: 'Record Equipment Return',
    actors: ['Lab Technician'],
    description: 'The technician inspects every returned unit and records its condition at return.',
  },
  {
    id: 'UC-09',
    name: 'Issue Fine',
    actors: [],
    description: 'Extension of the return: a fine is created only when the return is late or a unit is damaged.',
  },
  {
    id: 'UC-10',
    name: 'Pay Fine',
    actors: ['Student', 'E-wallet'],
    description: 'The student pays an outstanding fine online and the e-wallet returns the payment result.',
  },
  {
    id: 'UC-11',
    name: 'Log Unit Maintenance',
    actors: ['Lab Technician'],
    description: 'The technician records a maintenance job of a unit with its date, problem and cost.',
  },
  {
    id: 'UC-12',
    name: 'Retire Unit',
    actors: ['Lab Technician'],
    description: 'The technician marks a unit that can no longer be repaired as retired so it is never lent again.',
  },
  {
    id: 'UC-13',
    name: 'Manage Equipment Catalogue',
    actors: ['Lab Manager'],
    description: 'The manager maintains categories, models, descriptions and values of the equipment.',
  },
  {
    id: 'UC-14',
    name: 'Manage Technician Accounts',
    actors: ['Lab Manager'],
    description: 'The manager creates, updates and deactivates the accounts of lab technicians.',
  },
  {
    id: 'UC-15',
    name: 'View Lending Reports',
    actors: ['Lab Manager'],
    description: 'The manager reads the most borrowed models, overdue loans and damage cost per semester.',
  },
  {
    id: 'UC-16',
    name: 'Send Due-Date Reminder',
    actors: ['Notification Service'],
    description: 'Every evening the borrowers of loans due tomorrow are reminded through the notification service.',
  },
];

// Question 4 — conceptual ERD: identifiers + key attributes, cardinality on both ends, verb labels, no foreign keys.
const ERD = `erDiagram
  CATEGORY ||--o{ EQUIPMENT_MODEL : groups
  EQUIPMENT_MODEL ||--o{ EQUIPMENT_UNIT : "is realised by"
  STUDENT ||--o{ LOAN : submits
  LECTURER |o--o{ LOAN : approves
  LOAN ||--|{ LOAN_ITEM : includes
  EQUIPMENT_UNIT ||--o{ LOAN_ITEM : "is lent in"
  LOAN ||--o{ FINE : incurs
  FINE ||--o| PAYMENT : "is settled by"
  EQUIPMENT_UNIT ||--o{ MAINTENANCE_RECORD : has
  CATEGORY {
    string categoryId PK
    string name
  }
  EQUIPMENT_MODEL {
    string modelId PK
    string name
    string description
    decimal value
  }
  EQUIPMENT_UNIT {
    string serialNumber PK
    string condition
    string status
  }
  STUDENT {
    string studentId PK
    string fullName
    string email
  }
  LECTURER {
    string lecturerId PK
    string fullName
  }
  LOAN {
    string loanId PK
    string projectName
    date startDate
    date dueDate
    string status
  }
  LOAN_ITEM {
    string loanItemId PK
    string conditionAtReturn
    datetime returnedAt
  }
  FINE {
    string fineId PK
    decimal amount
    string reason
  }
  PAYMENT {
    string paymentId PK
    datetime paidAt
    decimal amount
  }
  MAINTENANCE_RECORD {
    string recordId PK
    date maintenanceDate
    string problem
    decimal cost
  }
`;

const ENTITIES = [
  {
    name: 'CATEGORY',
    description: 'A group of equipment models such as microcontrollers, measurement or imaging.',
    attributes: ['categoryId', 'name'],
  },
  {
    name: 'EQUIPMENT_MODEL',
    description: 'A kind of equipment in the catalogue, with its description and value; it is what students request.',
    attributes: ['modelId', 'name', 'description', 'value'],
  },
  {
    name: 'EQUIPMENT_UNIT',
    description: 'One physical device of a model, identified by its serial number, with its own condition and status.',
    attributes: ['serialNumber', 'condition', 'status'],
  },
  {
    name: 'STUDENT',
    description: 'A student who borrows equipment for a project and may owe fines.',
    attributes: ['studentId', 'fullName', 'email'],
  },
  {
    name: 'LECTURER',
    description: 'A project supervisor who approves requests containing high-value models.',
    attributes: ['lecturerId', 'fullName'],
  },
  {
    name: 'LOAN',
    description: 'One borrowing of one or more units by a student for a project, with its period and status.',
    attributes: ['loanId', 'projectName', 'startDate', 'dueDate', 'status'],
  },
  {
    name: 'LOAN_ITEM',
    description: 'One unit lent in one loan, with the condition recorded when that unit came back.',
    attributes: ['loanItemId', 'conditionAtReturn', 'returnedAt'],
  },
  {
    name: 'FINE',
    description: 'An amount owed because a loan was returned late or a unit was damaged.',
    attributes: ['fineId', 'amount', 'reason'],
  },
  {
    name: 'PAYMENT',
    description: 'The online e-wallet payment that settles one fine.',
    attributes: ['paymentId', 'paidAt', 'amount'],
  },
  {
    name: 'MAINTENANCE_RECORD',
    description: 'One maintenance job done on a unit with its date, problem and cost.',
    attributes: ['recordId', 'maintenanceDate', 'problem', 'cost'],
  },
];

